import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { authAPI } from '../utils/api';
import { getStoredUser, saveUserSession } from '../utils/session';

const Login = () => {
  const navigate = useNavigate();
  const [cnicBform, setCnicBform] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (getStoredUser()) {
      navigate('/dashboard', { replace: true });
    }
  }, [navigate]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    if (!cnicBform || cnicBform.length !== 13) {
      setError('Please enter a valid 13-digit CNIC/B-Form number');
      return;
    }

    setLoading(true);

    try {
      const response = await authAPI.login(cnicBform);
      
      saveUserSession(response.data.user);
      
      // Navigate to dashboard
      navigate('/dashboard');
    } catch (err) {
      setError(err.response?.data?.error || 'Login failed. Please check your CNIC/B-Form number.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <div className="header">
        <div className="header-content">
          <h1>🔑 Login</h1>
          <p>Gift of Reading Initiative</p>
        </div>
      </div>

      <div className="container">
        <div className="card" style={{ maxWidth: '500px', margin: '0 auto' }}>
          <div style={{ textAlign: 'center', marginBottom: '30px' }}>
            <div style={{ 
              fontSize: '4rem', 
              marginBottom: '15px',
              background: 'var(--gradient-primary)',
              WebkitBackgroundClip: 'text',
              WebkitTextFillColor: 'transparent'
            }}>
              📚
            </div>
            <h2 style={{ color: 'var(--color-page-text)', marginBottom: '10px' }}>Welcome Back!</h2>
            <p style={{ color: 'var(--color-muted-text)' }}>Enter your details to continue your reading journey</p>
          </div>

          {error && <div className="error">{error}</div>}

          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label>B-Form or CNIC Number</label>
              <input
                type="text"
                value={cnicBform}
                onChange={(e) => setCnicBform(e.target.value)}
                placeholder="Enter your 13-digit number"
                maxLength="13"
                pattern="[0-9]*"
                autoFocus
              />
              <small style={{ color: 'var(--color-muted-text)', fontSize: '0.9rem', display: 'block', marginTop: '5px' }}>
                Enter the same number you used during registration
              </small>
            </div>

            <button 
              type="submit" 
              className="btn" 
              style={{ width: '100%', marginTop: '20px' }}
              disabled={loading}
            >
              {loading ? 'Logging in...' : 'Login →'}
            </button>
          </form>

          <div style={{ 
            marginTop: '30px', 
            padding: '20px',
            background: 'var(--color-surface-muted)',
            borderRadius: 'var(--radius-md)',
            textAlign: 'center'
          }}>
            <p style={{ color: 'var(--color-muted-text)', marginBottom: '10px' }}>
              Don't have an account yet?
            </p>
            <button
              onClick={() => navigate('/register')}
              className="btn btn-secondary"
            >
              Register Now
            </button>
          </div>

          <div style={{ marginTop: '20px', textAlign: 'center' }}>
            <button
              onClick={() => navigate('/')}
              style={{
                background: 'none',
                border: 'none',
                color: 'var(--color-primary)',
                cursor: 'pointer',
                textDecoration: 'underline'
              }}
            >
              ← Back to Home
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;
